from pathlib import Path
p=Path('src/components/SupportLauncher.vue');s=p.read_text(encoding='utf-8-sig')
s=s.replace("import config from '@/store/config';","import config from '@/store/config';\nimport {urgentReminderMs,pendingUrgentTickets,urgentAnnouncement} from '@/utils/supportUrgency';")
