s=s.replace('.support-floating-button{position:fixed;', '.support-urgent-banner{position:fixed;right:18px;top:108px;width:420px;max-width:calc(100vw - 36px);z-index:13005;padding:18px;border:2px solid #d84242;border-radius:14px;background:#fff2f2;color:#722632;box-shadow:0 8px 28px #36131f33;font:15px/1.4 Arial,sans-serif}.support-urgent-banner p{margin:8px 0;overflow-wrap:anywhere}.support-urgent-banner small{display:block}.support-urgent-banner>div{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.support-urgent-banner button{padding:9px 11px;border:1px solid #c65a65;border-radius:7px;background:white;color:#742933;font-weight:bold}.support-urgent-banner button:first-child{background:#a42e43;color:white}.support-floating-button{position:fixed;',1)
